#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <stdlib.h>  /* for malloc/free */

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "syr2k.h"


/* Array initialization. */
static
void init_array(int n, int m,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < n; i++)
    for (j = 0; j < m; j++) {
      A[i][j] = (DATA_TYPE) ((i*j+1)%n) / n;
      B[i][j] = (DATA_TYPE) ((i*j+2)%m) / m;
    }
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      C[i][j] = (DATA_TYPE) ((i*j+3)%n) / m;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Precompute a transpose of B (size m x n) so that the B[j][k] access
     pattern in the innermost loop becomes contiguous in memory.
     This costs O(n*m) time and n*m extra elements of storage, which is
     < 50% of the original data footprint for all valid N,M.
   - Split the original loop nest into:
       1) a pure scaling phase C := beta*C
       2) a pure rank-2k update phase
     while preserving, for every C[i][j], the original per-element order:
       scale once, then add contributions for k=0..M-1 in increasing order.
   - Parallelize over i (rows of C) using OpenMP; each C[i][j] is written
     by a single thread, so there are no data races.
   - Hoist A[i][k] and B[i][k] out of the inner j-loop to avoid
     redundant loads.
   - Use local row pointers (Ci) and a row pointer into the transposed
     B_t to reduce index arithmetic and improve cache locality.

   Floating-point evaluation order for each C[i][j] over k is preserved
   relative to the original kernel; only independent operations on
   different (i,j) pairs are reordered and parallelized.
*/
static
void kernel_syr2k[[gnu::flatten, gnu::noinline]](int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

  const DATA_TYPE alpha_local = alpha;
  const DATA_TYPE beta_local  = beta;

  /* Allocate a temporary transpose of B.
     Layout: B_t[k][i] == B[i][k], with k in [0,m), i in [0,n).
     This turns the access B[j][k] in the innermost loop into a
     contiguous access B_t[k][j]. */
  DATA_TYPE (*B_t)[n] =
      (DATA_TYPE (*)[n]) malloc((size_t)m * (size_t)n * sizeof(DATA_TYPE));

  if (!B_t)
  {
    /* Fallback: allocation failed, run a cleaned-up version of the
       original kernel without the transpose.  Semantics are identical
       to the original code, with some redundant loads eliminated. */

#pragma scop
    for (i = 0; i < _PB_N; i++) {
      DATA_TYPE *Ci = C[i];

      /* Scale row i of the lower triangular part by beta. */
      for (j = 0; j <= i; j++)
        Ci[j] *= beta_local;

      /* Rank-2k update for row i. */
      for (k = 0; k < _PB_M; k++) {
        const DATA_TYPE aik = A[i][k];
        const DATA_TYPE bik = B[i][k];

        for (j = 0; j <= i; j++) {
          Ci[j] += A[j][k] * alpha_local * bik
                 + B[j][k] * alpha_local * aik;
        }
      }
    }
#pragma endscop
    return;
  }

  /* Build B^T once: B_t[k][i] = B[i][k].
     This O(n*m) preprocessing cost is negligible compared to the
     O(n^2*m) main kernel. */
  for (i = 0; i < n; ++i) {
    for (k = 0; k < m; ++k) {
      B_t[k][i] = B[i][k];
    }
  }

#pragma scop
  /* Parallel region containing both the scaling and update phases so that
     the OpenMP thread team is created only once. */
#pragma omp parallel private(i,j,k)
  {
    /* Phase 1: C := beta * C on the lower triangular part.
       Each C[i][j] (j<=i) is scaled exactly once. */
#pragma omp for schedule(static)
    for (i = 0; i < _PB_N; ++i) {
      DATA_TYPE *Ci = C[i];
      for (j = 0; j <= i; ++j) {
        Ci[j] *= beta_local;
      }
    }

    /* Phase 2: rank-2k update
          C := C + alpha * A * B^T + alpha * B * A^T
       over the lower triangular part (j <= i).  The per-element order of
       accumulation over k is the same as in the original code. */
#pragma omp for schedule(static)
    for (i = 0; i < _PB_N; ++i) {
      DATA_TYPE *Ci = C[i];

      for (k = 0; k < _PB_M; ++k) {
        const DATA_TYPE aik = A[i][k];
        const DATA_TYPE bik = B[i][k];

        /* Bcol_k[j] == B[j][k]; accesses along j are now contiguous. */
        const DATA_TYPE * restrict Bcol_k = B_t[k];

        /* Inner loop updates C[i][0..i].  This loop has no
           loop-carried dependences and is amenable to vectorization. */
        for (j = 0; j <= i; ++j) {
          Ci[j] += A[j][k]   * alpha_local * bik
                 + Bcol_k[j] * alpha_local * aik;
        }
      }
    }
  } /* end parallel region */
#pragma endscop

  free(B_t);
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syr2k (n, m,
		alpha, beta,
		POLYBENCH_ARRAY(C),
		POLYBENCH_ARRAY(A),
		POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
