/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Use local restrict-qualified aliases for A, B, C to improve
     the compiler's alias analysis.
   - Parallelize the outer loop over i with OpenMP; each iteration
     writes to a distinct row of C (lower triangle only), so there
     are no cross-iteration dependencies.
   - Reorder the (j,k) loops to make the innermost loop run along
     the contiguous dimension (k) of A and B, improving cache
     locality and enabling vectorization.
   - Accumulate C[i][j] in a scalar temporary (cij) to reduce
     memory traffic.
   - Use OpenMP 'simd' on the inner k-loop to explicitly allow
     vectorization.
 */
static
void kernel_syr2k[[gnu::flatten, gnu::noinline]](int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  /* Create local restrict-qualified aliases to help the optimizer.
     These pointers refer to disjoint arrays allocated in main, so
     the 'restrict' qualifier is valid and safe. */
  DATA_TYPE (*restrict C_)[n] = C;
  DATA_TYPE (*restrict A_)[m] = A;
  DATA_TYPE (*restrict B_)[m] = B;

  const DATA_TYPE alpha_local = alpha;
  const DATA_TYPE beta_local  = beta;

//BLAS PARAMS
//UPLO  = 'L'
//TRANS = 'N'
//A is NxM
//B is NxM
//C is NxN
#pragma scop
  /* Parallelize over rows of C. Each iteration i only writes to
     C[i][0..i], which is disjoint from all other iterations, so
     this is free of data races. If compiled without OpenMP support,
     this pragma is ignored and the code runs sequentially. */
#pragma omp parallel for schedule(static)
  for (int i = 0; i < _PB_N; i++) {
    /* Row pointers for the current i, kept outside inner loops to
       avoid recomputing address arithmetic. */
    DATA_TYPE *restrict       Ci = C_[i];
    const DATA_TYPE *restrict Ai = A_[i];
    const DATA_TYPE *restrict Bi = B_[i];

    /* 1) Scale the lower-triangular part of row i by beta. */
    for (int j = 0; j <= i; j++)
      Ci[j] *= beta_local;

    /* 2) Perform the symmetric rank-2k update:
           C[i][j] += alpha * sum_k ( A[j][k]*B[i][k] + B[j][k]*A[i][k] )
       We compute each C[i][j] as a dot-product over k. The k-loop
       walks contiguously along rows of A and B, improving cache
       locality and vectorization compared to the original layout
       (which walked down columns). */
    for (int j = 0; j <= i; j++) {
      DATA_TYPE cij = Ci[j];                 /* accumulate in a register */

      const DATA_TYPE *restrict Aj = A_[j];
      const DATA_TYPE *restrict Bj = B_[j];

      /* No loop-carried dependence on k: each iteration only updates
         the scalar 'cij'. This is safe to vectorize. */
#pragma omp simd reduction(+:cij)
      for (int k = 0; k < _PB_M; k++) {
        const DATA_TYPE aik = Ai[k];         /* A[i][k] */
        const DATA_TYPE bik = Bi[k];         /* B[i][k] */
        const DATA_TYPE ajk = Aj[k];         /* A[j][k] */
        const DATA_TYPE bjk = Bj[k];         /* B[j][k] */

        /* Factor alpha outside the inner products to reduce the
           number of multiplications. This is algebraically identical
           to the original expression:
             A[j][k]*alpha*B[i][k] + B[j][k]*alpha*A[i][k]
           => alpha * (A[j][k]*B[i][k] + B[j][k]*A[i][k])
         */
        cij += alpha_local * (ajk * bik + bjk * aik);
      }

      Ci[j] = cij;
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syr2k (n, m,
		alpha, beta,
		POLYBENCH_ARRAY(C),
		POLYBENCH_ARRAY(A),
		POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
