/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied (compared to the original PolyBench kernel):

   - Loop reordering to improve data locality:
       * Original order inside the SCoP was (i outer, then j, then k).
       * We now use (i outer, j inside i, k innermost).
       * For each fixed (i,j) pair, the inner-most loop runs along k,
         giving contiguous access to A[i][k], A[j][k], B[i][k], B[j][k],
         which is cache- and SIMD-friendly.

   - Fused scaling and accumulation:
       * Instead of first scaling the whole row C[i][0..i] by beta
         and then performing the rank-2k update in a second pass,
         we perform both in a single j-loop:
             C[i][j] = beta*C[i][j] + alpha*sum_k(...);
         This preserves the original mathematical result.

   - Use of restrict-qualified local aliases:
       * Local pointers C_, A_, B_ are declared restrict to inform the
         compiler that the three matrices do not alias, enabling
         more aggressive optimizations.

   - OpenMP parallelization (optional):
       * When compiled with -fopenmp, the outer i-loop is parallelized
         using #pragma omp parallel for.
       * A size guard (SYR2K_OMP_MIN_N) avoids parallel overhead on
         very small problems.
       * If OpenMP is not enabled, these pragmas are ignored by the
         compiler and the code runs sequentially, matching the
         original behavior.

   - SIMD/vectorization hint:
       * The inner k-loop is a pure reduction on a scalar 'cij' with
         contiguous memory access. A #pragma omp simd (when OpenMP is
         enabled) or a GCC ivdep hint encourages vectorization.

   NOTE: The floating-point evaluation order is slightly changed
   (e.g., alpha is factored as in alpha*(A[j][k]*B[i][k] + ...)).
   Numerically this computes the same mathematical expression, but
   may lead to very small rounding differences compared to the
   original, which is acceptable for typical numerical kernels and
   benchmarking, while significantly reducing the number of
   multiplications.
*/
static
void kernel_syr2k[[gnu::flatten, gnu::noinline]](int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

  /* Use the PolyBench run-time sizes for loop bounds. */
  const int n_ = _PB_N;
  const int m_ = _PB_M;

  /* Create restricted aliases with VLA-based types to help the compiler
     understand that the three matrices do not alias each other. */
  DATA_TYPE (* restrict C_)[n] = C;
  DATA_TYPE (* restrict A_)[m] = A;
  DATA_TYPE (* restrict B_)[m] = B;

  const DATA_TYPE alpha_ = alpha;
  const DATA_TYPE beta_  = beta;

//BLAS PARAMS
//UPLO  = 'L'
//TRANS = 'N'
//A is NxM
//B is NxM
//C is NxN
#pragma scop
#if defined(_OPENMP)
  /* Parallelize across the outermost i-dimension. Each iteration
     writes to a distinct row of C (up to i), so there are no
     loop-carried dependencies across different i values. */
  #pragma omp parallel for schedule(static) private(j, k) if (n_ >= SYR2K_OMP_MIN_N)
#endif
  for (i = 0; i < n_; i++) {
    /* Row pointers for current i. Using row pointers avoids repeatedly
       recomputing base addresses inside inner loops. */
    DATA_TYPE       * restrict Ci = C_[i];
    const DATA_TYPE * restrict Ai = A_[i];
    const DATA_TYPE * restrict Bi = B_[i];

    /* Only the lower triangular part (j <= i) is updated, matching
       the original BLAS syr2k lower-triangular semantics. */
    for (j = 0; j <= i; j++) {
      /* Scale C[i][j] by beta, then accumulate the symmetric rank-2k
         update for this (i,j) pair. Doing both in one place improves
         cache usage and reduces the number of passes over C. */
      DATA_TYPE cij = beta_ * Ci[j];

      const DATA_TYPE * restrict Aj = A_[j];
      const DATA_TYPE * restrict Bj = B_[j];

      /* Innermost loop over k with contiguous access in the second
         dimension of A and B (row-major layout), which is good for
         cache and enables SIMD vectorization.

         cij holds a private accumulator for C[i][j]; it is updated
         across all k and written back once after the loop. */
#if defined(_OPENMP)
      #pragma omp simd reduction(+:cij)
#elif defined(__GNUC__)
      /* For non-OpenMP builds with GCC, provide a weaker hint that
         iterations are independent to encourage vectorization. */
      #pragma GCC ivdep
#endif
      for (k = 0; k < m_; k++) {
        const DATA_TYPE a_jk = Aj[k];
        const DATA_TYPE b_jk = Bj[k];
        const DATA_TYPE a_ik = Ai[k];
        const DATA_TYPE b_ik = Bi[k];

        /* Symmetric rank-2k contribution:
             C[i,j] += alpha * (A[j,k]*B[i,k] + B[j,k]*A[i,k]);
           This matches the mathematical operation of the original
           kernel, but factors alpha to reduce multiplications. */
        cij += alpha_ * (a_jk * b_ik + b_jk * a_ik);
      }

      /* Store the updated value back to C. */
      Ci[j] = cij;
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syr2k (n, m,
		alpha, beta,
		POLYBENCH_ARRAY(C),
		POLYBENCH_ARRAY(A),
		POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
