static
void kernel_syr2k[[gnu::flatten, gnu::noinline]](int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  /* Create restrict-qualified local views of the input matrices.
     This helps the compiler with alias analysis and vectorization. */
  DATA_TYPE (* restrict C_)[n] = C;
  DATA_TYPE (* restrict A_)[m] = A;
  DATA_TYPE (* restrict B_)[m] = B;

  /* PolyBench may choose loop bounds smaller than the full sizes. */
  const int n_pb = _PB_N;
  const int m_pb = _PB_M;

  /* Temporary buffer: transpose of A.
     A is accessed as A[j][k] in the innermost loop of the original kernel,
     which is a strided access (stride = M) and thus cache-unfriendly.
     We build A_trans[k * n_pb + j] = A[j][k], so that j-varying accesses
     become unit-stride, improving data locality and SIMD efficiency.

     Extra storage: N*M elements, which is guaranteed to be <= 50% of the
     original footprint (C: N^2, A,B: 2*N*M). */
  DATA_TYPE * restrict A_trans =
    (DATA_TYPE *)polybench_alloc_data(
        (unsigned long long)n_pb * (unsigned long long)m_pb,
        sizeof(DATA_TYPE));

#pragma scop
  if (A_trans)
  {
    /* Build the transpose: A_trans[k * n_pb + i] = A[i][k]. */
    for (int i = 0; i < n_pb; ++i)
    {
      const DATA_TYPE * restrict Ai = A_[i];
      for (int k = 0; k < m_pb; ++k)
      {
        A_trans[(size_t)k * (size_t)n_pb + (size_t)i] = Ai[k];
      }
    }

    /* Scale the lower-triangular part of C by beta.
       This is O(N^2) work and relatively cheap compared to the O(N^2*M)
       update that follows, so we keep it sequential. */
    for (int i = 0; i < n_pb; ++i)
    {
      DATA_TYPE * restrict Ci = C_[i];
      for (int j = 0; j <= i; ++j)
      {
        Ci[j] *= beta;
      }
    }

    /* Main symmetric rank-2k update.
       Parallelize over i: each i-iteration writes a distinct row of C,
       so there are no loop-carried dependencies across i. */
#pragma omp parallel for schedule(static)
    for (int i = 0; i < n_pb; ++i)
    {
      DATA_TYPE * restrict Ci        = C_[i];
      const DATA_TYPE * restrict Ai  = A_[i];
      const DATA_TYPE * restrict Bi  = B_[i];

      for (int k = 0; k < m_pb; ++k)
      {
        /* Hoist the alpha scaling of A[i][k] and B[i][k] out of the j-loop.
           This reduces the number of multiplications in the innermost loop. */
        const DATA_TYPE aik_alpha = alpha * Ai[k];
        const DATA_TYPE bik_alpha = alpha * Bi[k];

        /* Column k of A (transposed) and B.
           - A_trans is laid out so that j varies with unit stride.
           - For B, elements B[j][k] are separated by the row stride m. */
        const DATA_TYPE * restrict Acol = &A_trans[(size_t)k * (size_t)n_pb];
        const DATA_TYPE * restrict Bcol = &B_[0][k];

        const DATA_TYPE * restrict Aj = Acol;
        const DATA_TYPE * restrict Bj = Bcol;

        /* Update the lower-triangular part: j in [0, i].
           Each iteration is independent, so we can safely vectorize. */
#pragma omp simd
        for (int j = 0; j <= i; ++j)
        {
          Ci[j] += (*Aj) * bik_alpha + (*Bj) * aik_alpha;

          /* Advance to the next row (j+1).  For A_trans, j is contiguous;
             for B, rows are stored with row stride m. */
          ++Aj;
          Bj += m;
        }
      }
    }
  }
  else
  {
