        const DATA_TYPE bik_alpha = alpha * Bi[k];

        for (int j = 0; j <= i; ++j)
        {
          Ci[j] += A_[j][k] * bik_alpha + B_[j][k] * aik_alpha;
        }
      }
    }
  }
